#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

struct Node *append(struct Node *head, int value) {
    struct Node *node = malloc(sizeof(struct Node));
    node->value = value;
    node->next = NULL;
    if (head == NULL) {
        return node;
    }
    struct Node *p = head;
    while (p->next != NULL) {
        p = p->next;
    }
    p->next = node;
    return head;
}

int main() {
    struct Node *head = NULL;
    head = append(head, 5);
    head = append(head, 6);
    head = append(head, 7);
    for (struct Node *p = head; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    printf("\n");
    return 0;
}
